    "voceSabia": "O subponto em zigue-zague foi apelidado pelos digitalizadores suíços de 'Ponto Colchão' porque ele cria uma base elástica que sustenta os fios superiores exatamente como as molas de um colchão de luxo!",
    "practicalExercise": "No seu software de matrizes, escreva um nome com letras de 25 mm de altura. Aplique subponto Zigzag em uma letra e deixe outra sem subponto. Faça a simulação de pontos e veja a camada de base sendo criada primeiro.",
