    "term": "Waffle Pique e Tecido Favo de Mel no Bordado (Waffle Weave Fabric & Honeycomb Pique Stabilization)",
    "pronunciation": "uá-fol pi-quê e te-ci-do fa-vo de mel no bor-da-do",
